set search_path = scheduler, public;
-- re-runnable: wipe the previous import (rows carrying excel_row), keep anything added in the app
delete from projects where excel_row is not null;
update status_history h set changed_at = coalesce(p.received_date, p.created_at::date)::timestamptz, note = 'imported from Quotation Register' from projects p where p.id = h.project_id and p.excel_row is not null and h.from_status is null;
update projects set completed_date = quote_submitted_date where status = 'COMPLETED' and completed_date is null and excel_row is not null;
